fn is_ascii_digit(c: char) -> bool {
    // Check if c is between '0' and '9' inclusive in ASCII range
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Check that all characters in the string are ASCII digits.
    // The empty string returns true vacuously.
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}